new file mode 100644
index 0000000000000000000000000000000000000000..2bdc619f956219cec9f3a2cd7d3277a2af6b9aa8
--- /dev/null
+++ b/test/runtime/samples/css-scoping-class/_config.js
@@ -0,0 +1,17 @@
+export default {
+	test ( assert, component, target ) {
+		const paragraph = target.querySelector('p');
+		const scopeClass = Array.from(paragraph.classList).find(name => /^svelte-\d+$/.test(name));
+
+		assert.ok(scopeClass);
+		assert.equal(paragraph.hasAttribute(scopeClass), false);
+		assert.equal(paragraph.classList.contains('foo'), true);
+
+		component.set({ className: 'bar' });
+
+		assert.equal(paragraph.classList.contains(scopeClass), true);
+		assert.equal(paragraph.classList.contains('bar'), true);
+		assert.equal(paragraph.classList.contains('foo'), false);
+		assert.equal(paragraph.hasAttribute(scopeClass), false);
+	}
+};
